// Callback dari Mayar — struktur payload bervariasi tergantung versi API.
// Mayar umumnya kirim data transaksi seperti:
// { data: { id, reference, payment_ref, amount, status, name, email, mobile, ... } }
// atau langsung field di root.

const raw = $input.first().json;
const body = raw.body || raw;  // n8n webhook: data ada di .body untuk JSON POST

// Coba baca dari berbagai kemungkinan struktur
const data = body.data || body;
const reference = data.reference || data.id || data.payment_ref || data.ref || '';
const amount = data.amount || 0;
const status = (data.status || data.payment_status || '').toString().toUpperCase();
const name = data.name || data.customer_name || '';
const email = data.email || data.customer_email || '';
const mobile = data.mobile || data.phone || '';

// Status PAID di Mayar bisa: 'PAID', 'PAID_BY_USER', 'SUCCESS', 'COMPLETED'
const isPaid = ['PAID','PAID_BY_USER','SUCCESS','COMPLETED'].includes(status);

return {
  json: {
    valid: true,
    reference: reference,
    amount: amount,
    status: status,
    isPaid: isPaid,
    name: name,
    email: email,
    mobile: mobile,
    raw: JSON.stringify(raw).slice(0, 2000)  // log mentah buat debug
  }
};

// Kirim data peserta ke Google Apps Script (auto-email-system.gs)
// Webhook Apps Script lo: URL dari Deploy > Web app
const APPS_SCRIPT_WEBHOOK = 'https://script.google.com/macros/s/XXX/exec';

const payment = $input.first().json;

return {
  json: {
    nama: payment.name || '',
    email: payment.email || '',
    no_wa: payment.mobile || '',
    harga: payment.amount || 299000,
    status: 'paid',
    tipe: 'umum',
    merchant_ref: payment.reference || '',
    endpoint: APPS_SCRIPT_WEBHOOK
  }
};

// Log callback yang bukan PAID (debug)
const payment = $input.first().json;
return {
  json: {
    log: 'CALLBACK BUKAN PAID',
    status: payment.status,
    reference: payment.reference,
    amount: payment.amount
  }
};
